namespace HobbyTracker.Api.Tests.Infrastructure;

/// <summary>
/// Real pictures, three pixels by two unless they say otherwise, written by Chromium's canvas
/// the way the app writes them, on 30 October 2026. Real rather than hand-made, because what
/// the server has to read is what a browser sends.
///
/// Chromium writes every WebP in the extended form, a VP8X chunk ahead of the picture, because
/// it embeds a colour profile. The two simple forms, a lone VP8 or VP8L chunk, are cut out of
/// those files, and Chromium decoded each at its size before it went in here.
/// </summary>
public static class Pictures
{
    public static byte[] Png => Convert.FromBase64String(
        "iVBORw0KGgoAAAANSUhEUgAAAAMAAAACCAYAAACddGYaAAAAGUlEQVR4AWJ6vtjuv6rJCjBmspuYxQADAAAAAP//zXNp1QAAAAZJREFUAwCSAAgFGZg8xgAAAABJRU5ErkJggg==");

    /// <summary>A JPEG at 85, with the colour profile and tables Chromium puts ahead of its frame.</summary>
    public static byte[] Jpeg => Convert.FromBase64String(
        "");

    /// <summary>The same JPEG two wide and three tall, which is what tells a width from a height.</summary>
    public static byte[] JpegPortrait => Convert.FromBase64String(
        "");

    /// <summary>A lossy WebP at 85, in the extended form Chromium writes: VP8X, a profile, then VP8.</summary>
    public static byte[] Webp => Convert.FromBase64String(
        "");

    /// <summary>A WebP with a pixel cleared, so extended for its alpha as well: VP8X, ALPH, VP8.</summary>
    public static byte[] WebpWithAlpha => Convert.FromBase64String(
        "");

    /// <summary>The simple lossy form: a lone VP8 chunk.</summary>
    public static byte[] WebpSimpleLossy => Convert.FromBase64String(
        "UklGRlQAAABXRUJQVlA4IEgAAACQAQCdASoDAAIAAQAcJagCdLoAA5gA/vk8RRJISLXOf/t2jHfE3wfcQLn0heop/7MZEX27/2Dj/pjIi+3f1PPbiBfs7k2ZMAA=");

    /// <summary>The simple lossless form: a lone VP8L chunk.</summary>
    public static byte[] WebpSimpleLossless => Convert.FromBase64String(
        "UklGRiIAAABXRUJQVlA4TBYAAAAvAkAAAA9wmreXCN8Sdf6DBxMQ0f8I");

    /// <summary>
    /// A PNG's header followed by nothing in particular, <paramref name="length"/> bytes in all.
    /// The server reads a picture's header and never decodes it, so this is a PNG as far as
    /// the server can tell, which is what a test about a size limit needs and nothing more.
    /// </summary>
    public static byte[] PngOfLength(int length)
    {
        var bytes = new byte[length];
        Png.AsSpan(0, 33).CopyTo(bytes);
        return bytes;
    }
}
